CREATE TABLE IF NOT EXISTS school_posts(id BIGSERIAL PRIMARY KEY,author_id BIGINT NOT NULL REFERENCES users(id),type VARCHAR(20) NOT NULL CHECK(type IN('notice','emergency')),title VARCHAR(200) NOT NULL,content TEXT NOT NULL,priority VARCHAR(20) NOT NULL CHECK(priority IN('normal','important','urgent')),expires_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS school_post_groups(post_id BIGINT REFERENCES school_posts(id) ON DELETE CASCADE,group_id BIGINT REFERENCES school_groups(id) ON DELETE CASCADE,PRIMARY KEY(post_id,group_id));
